package com.brannenservices.fieldassistant

import android.graphics.Bitmap
import android.graphics.Color
import android.util.Base64

object ApprovedRaster {
 private fun decode(w:Int,h:Int,pal:IntArray,data:String):Bitmap{
  val raw=Base64.decode(data,Base64.DEFAULT);val px=IntArray(w*h);var ri=0;var pi=0
  while(ri+1<raw.size&&pi<px.size){val n=raw[ri].toInt() and 255;val v=raw[ri+1].toInt() and 255;val color=if(v==255) Color.TRANSPARENT else pal[v];repeat(n){if(pi<px.size)px[pi++]=color};ri+=2}
  return Bitmap.createBitmap(px,w,h,Bitmap.Config.ARGB_8888)
 }
 private val fmPal=intArrayOf(-267048,-276577,-285594,-355496,-994111,-1075359,-3426394,-4550796,-1345464,-4426418,-3319499,-6206164,-8626872,-12757381,-9029081,-13157807,-6219495,-9755116,-11263977,-12967907,-15130313,-14808050,-16776896,-16777216)
 private const val fm=""
 private val flPal=intArrayOf(-1316898,-2782854,-627586,-5608895,-1420957,-6203335,-8041158,-13153677,-3262381,-10078412,-12700073,-15189123,-15322021,-3269318,-7202511,-11655362,-11791586,-14015425,-13888995,-15915691,-15523284,-15723996,-15924215,-16711419)
 private const val fl=""
 val floridaMan:Bitmap by lazy{decode(64,80,fmPal,fm)}
 val flamingo:Bitmap by lazy{decode(72,67,flPal,fl)}
}